    MOD = 1000000007

    def is_good(arr):
        r = len(arr)
        if r <= 1:
            return False
        for i in range(r):
            if abs(arr[i] - arr[(i + 1) % r]) != 1:
                return False
        return True

    def count_good_arrays(arr):
