    edge_list = []

    for i in range(1, len(lines)):
        parts = lines[i].split()
        if len(parts) < 3:
            continue
        a, b, c = int(parts[0]), int(parts[1]), int(parts[2])
        adj[a].append((b, c))
        adj[b].append((a, c))
        edge_list.append((a, b, c))

    if m == 0:
        return "YES\n" + " ".join(["0.0"] * n)

    visited = [False] * (n + 1)

    def solve_component(start):
        nonlocal visited

        component = []
        q = [start]
        visited[start] = True

        while q:
            u = q.pop(0)
            component.append(u)
            for v, _ in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)

        base = {}
        coef = {}

        def valid(u, b, c):
            if u in base:
                return abs(base[u] - b) < 1e-9 and abs(coef[u] - c) < 1e-9
            base[u] = b
            coef[u] = c
            return True

        stack = [(start, 0.0, 1.0)]
        while stack:
            u, b, c = stack.pop()
            for v, color in adj[u]:
                t_val = 1.0 if color == 1 else 2.0
                v_base = t_val - b
                v_coef = -c

                if v not in base:
                    stack.append((v, v_base, v_coef))
                elif not valid(v, v_base, v_coef):
                    return None

        # Find optimal t
        candidates = {0.0}
        for a in component:
            if abs(coef[a]) > 1e-9:
                c = -base[a] / coef[a]
                candidates.add(c)

        best_t = 0.0
        best_norm = float('inf')

        for t in candidates:
            norm = sum(abs(base[u] + coef[u] * t) for u in component)
            if norm < best_norm:
                best_norm = norm
                best_t = t

        return [base[u] + coef[u] * best_t for u in component]

    result = []
    for start in range(1, n + 1):
        if visited[start]:
            continue

        component_result = solve_component(start)
        if component_result is None:
            return "NO"

        result.extend(component_result)

    return "YES\n" + " ".join([f"{x:.6f}" for x in result])
