def solution(s):
    n = len(s)
    if n == 0:
        return "0\n"

    def is_palindrome(t):
        return t == t[::-1]

    max_total = 0
    best_k = 0
    best_ans = ""

    # Check k=1: entire string as middle (odd palindrome)
    if n % 2 == 1 and is_palindrome(s):
        max_total = max(max_total, n)
        if n > max_total:
            best_k = 1
            best_ans = f"1\n1 {n}\n"

    # Check k=3: prefix + middle + suffix
    # where prefix and suffix are reverses of equal length, middle is odd palindrome
    for i in range(n):
        for j in range(i+1, n):
            len1 = j - i
            prefix = s[i:j]
            reverse_prefix = prefix[::-1]

            for k in range(j+1, n):
                len2 = k - j
                middle = s[j:k]
                if len2 % 2 != 1:
                    continue
                if not is_palindrome(middle):
                    continue

                for l in range(k+1, n+1):
                    len3 = l - k
                    suffix = s[k:l]

                    if len3 > 0 and suffix == reverse_prefix:
                        total = len1 + len2 + len3
                        if total > max_total:
                            max_total = total
                            best_k = 3
                            best_ans = f"3\n{i+1} {len1}\n{j+1} {len2}\n{k+1} {len3}\n"

    # Fallback: find any valid 3-part solution or longest palindrome
    if best_k == 0:
        if max_total > 0 and best_k == 1:
            return best_ans
        # Find longest odd palindrome
        for i in range(n):
            for j in range(i+2, n):
                if (j-i+1) % 2 == 1 and is_palindrome(s[i:j+1]):
                    if j - i + 1 > max_total or (j - i + 1 == max_total and best_k < 3):
                        max_total = j - i + 1
                        best_k = 1
                        best_ans = f"1\n{i+1} {j-i+1}\n"
    else:
        return best_ans

    return best_ans


